BEGIN;CREATE SCHEMA lab_test;REVOKE ALL ON SCHEMA lab_test FROM PUBLIC;GRANT USAGE ON SCHEMA lab_test TO authenticated,anon;
CREATE FUNCTION lab_test.claim(u uuid,r text)RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$BEGIN PERFORM set_config('request.jwt.claim.sub',coalesce(u::text,''),true);PERFORM set_config('request.jwt.claim.role',r,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role',r)::text,true);END$$;
CREATE FUNCTION lab_test.entity_id(c text)RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT id FROM public.entities WHERE short_code=c$$;
CREATE FUNCTION lab_test.branch_id(c text)RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT b.id FROM public.branches b JOIN public.entities e ON e.id=b.entity_id WHERE e.short_code='IETA'AND b.branch_code=c$$;
CREATE FUNCTION lab_test.probe(q text)RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$DECLARE ok boolean:=false;BEGIN BEGIN EXECUTE q;ok:=true;RAISE EXCEPTION USING ERRCODE='PT001';EXCEPTION WHEN SQLSTATE'PT001'THEN RETURN ok;WHEN OTHERS THEN RETURN false;END;END$$;
CREATE FUNCTION lab_test.student(e uuid,b uuid)RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$DECLARE i uuid:=gen_random_uuid();num text;ok boolean:=false;BEGIN BEGIN num:=public.generate_student_number(e);INSERT INTO public.students(id,entity_id,student_number,full_name,preferred_name,identity_document_type,identity_number_protected,phone,email,home_branch_id,lifecycle_status,created_by,updated_by)VALUES(i,e,num,'Fictional Regression Student','Before','other','LOCAL-ONLY-4321','+60129994321','regression@example.invalid',b,'draft',auth.uid(),auth.uid());UPDATE public.students SET preferred_name='After'WHERE id=i;SELECT count(*)=1 AND bool_and(preferred_name='After')AND bool_and(identity_number_masked LIKE'%4321')AND bool_and(identity_number_masked<>'LOCAL-ONLY-4321')INTO ok FROM public.students_staff_safe WHERE id=i;RAISE EXCEPTION USING ERRCODE='PT001';EXCEPTION WHEN SQLSTATE'PT001'THEN RETURN coalesce(ok,false);WHEN OTHERS THEN RETURN false;END;END$$;
CREATE FUNCTION lab_test.academic(e uuid,b uuid,s uuid)RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$DECLARE p uuid:=gen_random_uuid();i uuid:=gen_random_uuid();n uuid:=gen_random_uuid();z text:=substring(replace(gen_random_uuid()::text,'-',''),1,8);en text;ok boolean:=false;BEGIN BEGIN INSERT INTO public.programmes(id,entity_id,programme_code,programme_name,duration_value,duration_unit)VALUES(p,e,'L'||z,'Fictional Programme',6,'months');UPDATE public.programmes SET programme_name='Fictional Programme Edited'WHERE id=p;INSERT INTO public.programme_intakes(id,programme_id,entity_id,branch_id,intake_code,intake_name,start_date,status)VALUES(i,p,e,b,'I'||z,'LBT',DATE'2026-09-01','open');UPDATE public.programme_intakes SET remarks='Edited'WHERE id=i;en:=public.generate_enrolment_number(e,b,i);INSERT INTO public.enrolments(id,enrolment_number,student_id,programme_id,intake_id,entity_id,branch_id,status)VALUES(n,en,s,p,i,e,b,'draft');UPDATE public.enrolments SET remarks='Edited'WHERE id=n;SELECT EXISTS(SELECT 1 FROM public.programmes p1 JOIN public.programme_intakes i1 ON i1.programme_id=p1.id JOIN public.enrolments n1 ON n1.intake_id=i1.id WHERE p1.id=p AND p1.programme_name LIKE'%Edited'AND i1.remarks='Edited'AND n1.enrolment_number=en AND n1.remarks='Edited')INTO ok;RAISE EXCEPTION USING ERRCODE='PT001';EXCEPTION WHEN SQLSTATE'PT001'THEN RETURN coalesce(ok,false);WHEN OTHERS THEN RETURN false;END;END$$;
CREATE FUNCTION lab_test.import_flow(e uuid,b uuid)RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$DECLARE x uuid:=gen_random_uuid();r uuid:=gen_random_uuid();s uuid;ok boolean:=false;BEGIN BEGIN INSERT INTO public.student_import_batches(id,entity_id,default_branch_id,filename,file_type,status,uploaded_by)VALUES(x,e,b,'fictional.csv','csv','mapping',auth.uid());INSERT INTO public.student_import_rows(id,student_import_batch_id,row_number,original_data)VALUES(r,x,1,'{}');DELETE FROM public.student_import_rows WHERE student_import_batch_id=x;r:=gen_random_uuid();INSERT INTO public.student_import_rows(id,student_import_batch_id,row_number,original_data)VALUES(r,x,1,'{}');PERFORM public.confirm_student_import_row(r,jsonb_build_object('full_name','Fictional Imported','preferred_name','Imported','identity_document_type','other','identity_number','IMPORT-7788','date_of_birth','2001-02-03','gender','female','phone','+60128887788','email','import@example.invalid','education_level','Fictional','address','Local'),'import_as_new',NULL);SELECT created_student_id INTO s FROM public.student_import_rows WHERE id=r;UPDATE public.student_import_batches SET status='completed'WHERE id=x;PERFORM public.revert_student_import_batch(x);SELECT EXISTS(SELECT 1 FROM public.student_import_batches WHERE id=x AND status='reverted')AND EXISTS(SELECT 1 FROM public.student_import_rows WHERE id=r AND row_status='reverted')AND NOT EXISTS(SELECT 1 FROM public.students WHERE id=s)INTO ok;RAISE EXCEPTION USING ERRCODE='PT001';EXCEPTION WHEN SQLSTATE'PT001'THEN RETURN coalesce(ok,false);WHEN OTHERS THEN RETURN false;END;END$$;
CREATE FUNCTION lab_test.merge_ok(s uuid,t uuid)RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$DECLARE ok boolean:=false;BEGIN BEGIN PERFORM public.merge_students(s,t,'Local rollback test');SELECT EXISTS(SELECT 1 FROM public.students WHERE id=s AND lifecycle_status='merged'AND merged_into_student_id=t)AND EXISTS(SELECT 1 FROM public.student_merge_events WHERE source_student_id=s AND target_student_id=t)AND EXISTS(SELECT 1 FROM public.audit_logs WHERE action='students_merged'AND entity_id=(SELECT entity_id FROM public.students WHERE id=t)AND payload->>'target_student_id'=t::text)INTO ok;RAISE EXCEPTION USING ERRCODE='PT001';EXCEPTION WHEN SQLSTATE'PT001'THEN RETURN coalesce(ok,false);WHEN OTHERS THEN RETURN false;END;END$$;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA lab_test TO authenticated,anon;
