DO $$BEGIN IF(SELECT count(*) FROM public.app_profiles WHERE id IN('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','55555555-5555-4555-8555-555555555555'))<>5 THEN RAISE EXCEPTION 'Expected exactly five trigger-created fictional app_profiles';END IF;IF EXISTS(SELECT 1 FROM(VALUES('11111111-1111-4111-8111-111111111111'::uuid,'owner',true),('22222222-2222-4222-8222-222222222222','branch_manager',true),('33333333-3333-4333-8333-333333333333','branch_manager',true),('44444444-4444-4444-8444-444444444444','read_only',true),('55555555-5555-4555-8555-555555555555','branch_manager',false))v(id,role,active_status)LEFT JOIN public.app_profiles p ON p.id=v.id WHERE p.id IS NULL OR p.role<>v.role OR p.active_status<>v.active_status)THEN RAISE EXCEPTION 'Fictional app_profiles role/status fixture assertion failed';END IF;END$$;
